package com.google.gson;
public abstract class JsonElement { public JsonObject getAsJsonObject() { return null; } public JsonArray getAsJsonArray() { return null; } public JsonPrimitive getAsJsonPrimitive() { return null; } public String getAsString() { return null; } public int getAsInt() { return 0; } public long getAsLong() { return 0; } public float getAsFloat() { return 0; } public double getAsDouble() { return 0; } public boolean getAsBoolean() { return false; } public Number getAsNumber() { return null; } public boolean isJsonObject() { return false; } public boolean isJsonArray() { return false; } public boolean isJsonPrimitive() { return false; } public boolean isJsonNull() { return false; } public JsonElement deepCopy() { return null; } }
